        </div>
        <div class="col-md-6">
            <label class="form-label">Phone</label>
            <input type="tel" class="form-control" value="@Reference.Phone"
                   @onchange="e => Update(Reference with { Phone = e.Value?.ToString() ?? "" })" />
        </div>
    </div>
