</div>

@code {
    [Parameter, EditorRequired] public Reference Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<Reference> OnReferenceChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task Update(Reference updated)
    {
        await OnReferenceChanged.InvokeAsync(updated);
    }
}

@using sv_c9dbfb528f15491789824a47b566e585.Models

<div class="personal-info-step">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="mb-3">
        <label class="form-label">Full Name *</label>
        <input type="text" class="form-control" value="@FullName"
               @onchange="e => FullName = e.Value?.ToString() ?? "" " />
    </div>

    <div class="mb-3">
        <label class="form-label">Email *</label>
        <input type="email" class="form-control" value="@Email"
               @onchange="e => Email = e.Value?.ToString() ?? "" " />
    </div>

    <div class="mb-3">
        <label class="form-label">Phone *</label>
        <input type="tel" class="form-control" value="@Phone"
               @onchange="e => Phone = e.Value?.ToString() ?? "" " />
    </div>

    <div class="mb-3">
        <label class="form-label">Address *</label>
        <textarea class="form-control" rows="2" value="@Address"
                  @onchange="e => Address = e.Value?.ToString() ?? "" "></textarea>
    </div>

    <div class="d-flex justify-content-end">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo? Info { get; set; }
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string FullName = "";
    private string Email = "";
    private string Phone = "";
    private string Address = "";
    private string? ErrorMessage;
    private bool IsValidating;

    protected override void OnParametersSet()
    {
        if (Info is not null)
        {
            FullName = Info.FullName;
            Email = Info.Email;
            Phone = Info.Phone;
            Address = Info.Address;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Email);
            IsValidating = false;

            if (!isValid)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
    }
}

@using sv_c9dbfb528f15491789824a47b566e585.Models

<div class="work-history-step">
    <h3>Work History</h3>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
        + Add Another Position
    </button>

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public WorkHistory? History { get; set; }
    [Parameter] public EventCallback<WorkHistory> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<WorkEntry> Entries = new();
    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (History is not null && History.Entries.Count > 0)
        {
            Entries = History.Entries.ToList();
        }
        else if (Entries.Count == 0)
        {
            Entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
        }
    }

    private void UpdateEntry(int index, WorkEntry updated)
    {
        Entries[index] = updated;
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(new WorkHistory(Entries.ToList()));
    }
}

@using sv_c9dbfb528f15491789824a47b566e585.Models

<div class="references-step">
    <h3>References</h3>
    <p class="text-muted">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="@References[index]"
                       Index="index"
                       CanRemove="@(References.Count > 1)"
                       OnReferenceChanged="r => UpdateReference(index, r)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
            + Add Reference
        </button>
    }

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference>? ExistingReferences { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<Reference> References = new();

    protected override void OnParametersSet()
    {
        if (ExistingReferences is not null && ExistingReferences.Count > 0)
        {
            References = ExistingReferences.ToList();
        }
        else if (References.Count == 0)
        {
            References.Add(new Reference("", "", "", ""));
            References.Add(new Reference("", "", "", ""));
        }
    }

    private void UpdateReference(int index, Reference updated)
    {
        References[index] = updated;
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 1)
            References.RemoveAt(index);
    }

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new Reference("", "", "", ""));
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(References.ToList());
    }
}

@using sv_c9dbfb528f15491789824a47b566e585.Models

<div class="review-step">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h4>Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Personal Information</strong>
                <a href="#" @onclick="() => OnEditStep.InvokeAsync(0)" @onclick:preventDefault>Edit</a>
            </div>
            <div class="card-body">
                <p><strong>Name:</strong> @Personal?.FullName</p>
                <p><strong>Email:</strong> @Personal?.Email</p>
                <p><strong>Phone:</strong> @Personal?.Phone</p>
                <p><strong>Address:</strong> @Personal?.Address</p>
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Work History</strong>
                <a href="#" @onclick="() => OnEditStep.InvokeAsync(1)" @onclick:preventDefault>Edit</a>
            </div>
            <div class="card-body">
                @if (Work?.Entries is not null)
                {
                    @foreach (var entry in Work.Entries)
                    {
                        <div class="mb-2">
                            <p class="mb-1"><strong>@entry.Title</strong> at @entry.Company</p>
                            <p class="mb-1 text-muted">
                                @entry.StartDate.ToString("MMM yyyy") &ndash;
                                @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                            </p>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mb-0">@entry.Description</p>
                            }
                        </div>
                        <hr />
                    }
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
