@page "/apply"
@using sv_c9dbfb528f15491789824a47b566e585.Models
@using sv_c9dbfb528f15491789824a47b566e585.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnStepSelected="GoToStep" />

    <div class="mt-4">
        @switch (currentStep)
