+                break;
+        }
+    </div>
+</div>
+
+@code {
+    private int currentStep = 0;
+    private PersonalInfo? personalInfo;
+    private WorkHistory? workHistory;
+    private List<Reference>? references;
+    private string? coverLetter;
+
+    private void GoToStep(int step)
+    {
+        currentStep = step;
+    }
+
+    private void GoBack()
+    {
+        if (currentStep > 0)
+            currentStep--;
+    }
+
+    private void HandlePersonalNext(PersonalInfo info)
+    {
+        personalInfo = info;
+        currentStep = 1;
+    }
+
+    private void HandleWorkNext(WorkHistory history)
+    {
+        workHistory = history;
+        currentStep = 2;
+    }
+
+    private void HandleReferencesNext(List<Reference> refs)
+    {
+        references = refs;
+        currentStep = 3;
+    }
+
+    private void HandleCoverLetterNext(string letter)
+    {
+        coverLetter = letter;
+        currentStep = 4;
+    }
+
+    private async Task<int> SubmitApplication()
+    {
+        var application = new JobApplication(
+            personalInfo!,
+            workHistory!,
+            references!,
+            coverLetter ?? ""
+        );
+        return await ApplicationService.SubmitApplicationAsync(application);
+    }
+}
+

