@using sv_c9dbfb528f15491789824a47b566e585.Models

<div class="work-entry-form">
    <div class="d-flex justify-content-between align-items-center mb-2">
        <h5>Position @(Index + 1)</h5>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Company Name *</label>
        <input type="text" class="form-control" value="@Entry.Company"
               @onchange="CompanyChanged" />
    </div>

    <div class="mb-3">
        <label class="form-label">Job Title *</label>
        <input type="text" class="form-control" value="@Entry.Title"
               @onchange="TitleChanged" />
    </div>

    <div class="row mb-3">
        <div class="col-md-6">
            <label class="form-label">Start Date *</label>
            <input type="date" class="form-control" value="@StartDateStr"
                   @onchange="StartDateChanged" />
        </div>
        <div class="col-md-6">
            <label class="form-label">End Date</label>
            <input type="date" class="form-control" value="@EndDateStr"
                   disabled="@IsCurrent"
                   @onchange="EndDateChanged" />
            <div class="form-check mt-1">
                <input type="checkbox" class="form-check-input" id="@CurrentId" checked="@IsCurrent"
                       @onchange="OnCurrentChanged" />
                <label class="form-check-label" for="@CurrentId">Currently working here</label>
            </div>
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label">Description</label>
        <textarea class="form-control" rows="3" value="@Entry.Description"
                  @onchange="DescriptionChanged"></textarea>
    </div>
    <hr />
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate == null;
    private string StartDateStr => Entry.StartDate.ToString("yyyy-MM-dd");
    private string EndDateStr => Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty;
    private string CurrentId => $"current-{Index}";

    private Task CompanyChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Company = e.Value?.ToString() ?? string.Empty });

    private Task TitleChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Title = e.Value?.ToString() ?? string.Empty });

    private Task StartDateChanged(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        if (DateTime.TryParse(val, out var date))
            return OnEntryChanged.InvokeAsync(Entry with { StartDate = date });
        return Task.CompletedTask;
    }

    private Task EndDateChanged(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        var endDate = string.IsNullOrEmpty(val) ? (DateTime?)null : DateTime.Parse(val);
        return OnEntryChanged.InvokeAsync(Entry with { EndDate = endDate });
    }

    private Task DescriptionChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Description = e.Value?.ToString() ?? string.Empty });

    private Task OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        return OnEntryChanged.InvokeAsync(updated);
    }
}

